function qs(obj){var p=new URLSearchParams();Object.keys(obj).forEach(function(k){if(obj[k]!==""&&obj[k]!=null)p.set(k,obj[k]);});return p.toString();}
function catalogTargetId(context,kind){return context==="manage_type"&&kind==="modpack"?"packResults":context==="manage_mod"&&kind==="mod"?"modResults":context==="manage_plugin"&&kind==="plugin"?"pluginResults":context==="manage_addon"&&kind==="bedrock_addon"?"addonResults":"modalResults";}
function syncCatalogControls(){var c=state.catalog;if(!c)return;document.querySelectorAll(".provider-button").forEach(function(b){var active=b.dataset.platform===c.platform;b.classList.toggle("selected",active);b.setAttribute("aria-pressed",String(active));});document.querySelectorAll(".catalog-view-button").forEach(function(b){var active=b.dataset.layout===(state.catalogLayout[c.kind]||"grid");b.classList.toggle("selected",active);b.setAttribute("aria-pressed",String(active));});}
