content.innerHTML='<h2 id="dialogTitle">Choose a Minecraft version</h2><p class="dialog-copy">'+esc(title)+' will use the exact release or snapshot ID selected here.</p><div class="version-toolbar"><div class="version-channels"><button type="button" class="small-button'+(dlg.channel==="release"?" selected":"")+'" data-action="version-channel" data-channel="release">Releases</button><button type="button" class="small-button'+(dlg.channel==="snapshot"?" selected":"")+'" data-action="version-channel" data-channel="snapshot"'+snapshotDisabled+'>Snapshots</button></div><input id="versionSearch" class="search-input" type="search" placeholder="Filter by version" value="'+esc(dlg.query||"")+'"></div><div id="nativeVersionRows" class="version-list native-version-list"></div><div class="dialog-footer"><span class="dialog-footer-note">'+(snapshotAllowed?"Version IDs are read from Mojang and passed to the server image.":"Snapshots are unavailable for Bukkit, Paper, and Purpur. Choose a release.")+'</span><button id="continueNative" class="primary-button" type="button" data-action="continue-native"'+(dlg.selectedVersion?"":" disabled")+'>Continue</button></div>';
