function perform(label,fn){if(state.busy)return;state.busy=true;notify(label+"…");Promise.resolve().then(fn).then(function(r){if(r&&r.job_id){notify(label+" queued. It will continue in the background.");watchJob(r.job_id,label);}else{state.busy=false;notify(label+" complete.","success");refresh();}}).catch(function(e){state.busy=false;notify(e.message,"error");refresh();});}
function watchJob(id,label){var started=Date.now();function check(){api("jobs/"+encodeURIComponent(id)).then(function(j){if(j.state==="complete"){state.busy=false;notify(label+" complete.","success");refresh();}else if(j.state==="failed"){state.busy=false;notify(j.message||label+" failed.","error");refresh();}else if(Date.now()-started>240000){state.busy=false;notify(label+" is still running. Check the server status or logs.");refresh();}else setTimeout(check,1400);}).catch(function(){setTimeout(check,2200);});}setTimeout(check,1000);}
function updateConsoleOutput(){var output=document.getElementById("consoleOutput"),id=state.consoleId;if(!output||!id)return;var nearBottom=output.scrollHeight-output.scrollTop-output.clientHeight<48;apiText("servers/"+encodeURIComponent(id)+"/logs").then(function(t){if(!document.getElementById("consoleOutput"))return;output.textContent=(t||"Waiting for server output…")+(state.consoleTranscript&&state.consoleTranscript.length?"\n\n"+state.consoleTranscript.join("\n\n"):"");if(nearBottom)output.scrollTop=output.scrollHeight;}).catch(function(){});}
function consoleView(id){var s=state.servers.find(function(x){return x.id===id;});state.consoleId=id;state.consoleTranscript=[];apiText("servers/"+encodeURIComponent(id)+"/logs").then(function(t){if(state.consoleId!==id)return;showDialog("SERVER CONSOLE",'<h2 id="dialogTitle">'+esc(s?s.name:"Server")+'</h2><p class="dialog-copy">Live server output and command input.</p><pre id="consoleOutput" class="log-output console-output">'+esc(t||"Waiting for server output…")+'</pre><form id="consoleForm" class="console-form"><input class="field" id="consoleCommand" name="command" maxlength="512" autocomplete="off" placeholder="Enter a server command, for example: say Hello" aria-label="Server command" required><button class="primary-button" type="submit">Send</button></form>',{type:"console",id:id});var output=document.getElementById("consoleOutput");if(output)output.scrollTop=output.scrollHeight;state.consoleTimer=setInterval(updateConsoleOutput,1800);}).catch(function(e){state.consoleId=null;notify(e.message,"error");});}
