function removeServer(id){id=id||state.active;var s=state.servers.find(function(x){return x.id===id;});if(!s)return;if(!confirm("Remove “"+s.name+"”? Its container and saved world directory will be permanently deleted."))return;if(state.active===id)leaveManage();else closeServerMenus();perform("Removing server",function(){return api("servers/"+encodeURIComponent(id),{method:"DELETE"});});}
